-- 悦航购商超品类与商品种子数据
-- 参考：小象超市/盒马鲜生等前置仓商超的品类组织方式（蔬菜/水果/肉禽蛋/海鲜水产/乳品烘焙/熟食预制菜等）
-- 内容：12 个一级类目、51 个二级类目、42 个品牌、106 个在售商品及默认 SKU，全部挂主租户 1590229800633634816
-- 特性：可重复执行；仅按 95x 人工编排前缀清理本脚本自身的种子数据，不触碰存量业务数据
-- 说明：商品图 spu_urls / category_pic 暂留空，请运营在管理后台上传图片后回填
-- 执行：mysql -u root -p aryn_boot < 41grocery_catalog_seed.sql（Boot 单体模式，目标库 aryn_boot）

USE `aryn_boot`;
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- ---------- 清理本脚本历史种子（幂等） ----------
DELETE FROM `goods_sku` WHERE `id` LIKE '955%';
DELETE FROM `goods_spu` WHERE `id` LIKE '954%';
DELETE FROM `goods_category` WHERE `id` LIKE '951%' OR `id` LIKE '952%';
DELETE FROM `goods_brand` WHERE `id` LIKE '953%';

